using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.VFX;
namespace MassiveArmy.Planetary
{
    [DefaultExecutionOrder(-220)]public sealed class PlanetShipWeaponsTest:MonoBehaviour
    {
        [Serializable]sealed class Report{public string status="PASS",error="";public List<string> checks=new List<string>();public int fired,exploded,timedOut,rocketPixels,burstPixels,burstParticles;public float nukeDepth,zombieTravel;public double impactSubmissionMs;}
        readonly Report report=new Report();PlanetDevelopment world;PlanetSpacecraft ship;string output;RenderTexture target;
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(!Application.isEditor&&Array.IndexOf(Environment.GetCommandLineArgs(),"-planet-ship-weapons-test")>=0)new GameObject("Ship weapons regression").AddComponent<PlanetShipWeaponsTest>();}
        void Awake(){var args=Environment.GetCommandLineArgs();output=args[Array.IndexOf(args,"-planet-output")+1];Directory.CreateDirectory(output);world=FindAnyObjectByType<PlanetDevelopment>();world.currentRtsContent=true;world.configuredRadius=120000;world.deformTerrainOnNuke=true;world.ambientZombies=0;world.requestedCapacity=16384;Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;}
        void Start(){StartCoroutine(Guard());}
        void Check(bool value,string text){if(!value)throw new InvalidOperationException(text);report.checks.Add(text);}
        IEnumerator Guard(){var run=Run();while(true){object next;try{if(!run.MoveNext())break;next=run.Current;}catch(Exception e){report.status="FAIL";report.error=e.ToString();Debug.LogException(e);break;}yield return next;}File.WriteAllText(Path.Combine(output,"validation.json"),JsonUtility.ToJson(report,true));Application.Quit(report.status=="PASS"?0:1);}
        Color32[] Capture(string name){RenderPipeline.SubmitRenderRequest(world.View,new RenderPipeline.StandardRequest{destination=target});var old=RenderTexture.active;RenderTexture.active=target;var image=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,target.width,target.height),0,0);image.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),image.EncodeToPNG());var pixels=image.GetPixels32();Destroy(image);RenderTexture.active=old;return pixels;}
        void SetShip(Double3 position,Vector3 forward,Vector3 up,Double3 velocity){ship.SetFlightStateForValidation(new SpacePose{position=position,linearVelocity=velocity,rotation=Quaternion.LookRotation(forward,up)});ship.Rebase();Physics.SyncTransforms();}
        bool Fire(){world.Paused=false;ship.StepWeapons(.1f);bool fired=ship.TryFireRocket();world.Paused=true;return fired;}
        void Cool(){world.Paused=false;for(int i=0;i<7;i++)ship.StepWeapons(.1f);world.Paused=true;}
        UnitState ReadUnit(int index){var data=new UnitState[1];world.UnitsForValidation.GetData(data,0,index,1);return data[0];}
        IEnumerator Run(){double deadline=Time.realtimeSinceStartupAsDouble+120;while(world.ShipForValidation==null){if(Time.realtimeSinceStartupAsDouble>deadline)throw new TimeoutException();yield return null;}ship=world.ShipForValidation;world.Paused=true;world.AutomaticPlayerStep=false;world.Rig.InputEnabled=false;var surface=new PlanetSurface(world.definition);var encounter=world.EncounterForValidation;
            world.Paused=false;Check(!ship.TryFireRocket(),"Ship weapons reject firing outside the pilot seat");world.Paused=true;world.SetShipControl(true);Check(!ship.TryFireRocket(),"Paused pilot cannot fire");
            var up=world.Base.Homes[0];var east=Vector3.Cross(Vector3.up,up).normalized;var start=new Double3(up)*(world.definition.radius+1000);var carried=new Double3(east)*125;SetShip(start,up,east,carried);
            Check(Fire(),"Pilot seat launches a rocket from an exterior muzzle");Check((ship.RocketVelocityForValidation-carried-new Double3(up)*320).Magnitude<.02,"Rocket inherits ship velocity plus forward launch speed");Check(!Fire(),"Rocket cooldown prevents duplicate immediate shots");Check((ship.RocketPositionForValidation-start).Magnitude>40,"Rocket begins outside the hull rather than at the camera");
            var first=ship.RocketPositionForValidation;ship.StepWeapons(.1f);Check((ship.RocketPositionForValidation-first).Magnitude<1e-8,"Pause freezes airborne rockets");ship.IntegrateRockets(.1f);Check((ship.RocketPositionForValidation-first).Magnitude>30,"Rocket physically travels before exploding");
            target=new RenderTexture(1600,1000,24,RenderTextureFormat.ARGBHalf);target.Create();world.View.enabled=false;world.View.targetTexture=target;ship.ShowRocketVisuals=false;for(int i=0;i<3;i++)yield return null;var without=Capture("without-rocket");ship.ShowRocketVisuals=true;for(int i=0;i<3;i++)yield return null;var withRocket=Capture("rocket-in-flight");for(int i=0;i<withRocket.Length;i++)if(withRocket[i].r>without[i].r+20&&withRocket[i].r>withRocket[i].g*1.1f&&withRocket[i].g>withRocket[i].b)report.rocketPixels++;Check(report.rocketPixels>12,"Rocket and orange exhaust visibly render through the cockpit camera");
            world.SetShipControl(false);Check(!ship.TryFireRocket(),"Leaving the seat disables new shots");int beforeTimeout=ship.RocketsTimedOut;for(int i=0;i<2250;i++)ship.IntegrateRockets(.02f);Check(ship.ActiveRockets==0&&ship.RocketsTimedOut==beforeTimeout+1,"An outward space shot detonates after its finite fuse even after leaving the pilot seat");Check(encounter.RocketImpacts==0,"A distant space detonation does not damage the planet underneath");
            world.SetShipControl(true);SetShip(start,up,east,carried);Cool();for(int n=0;n<PlanetSpacecraft.RocketCapacity;n++){Check(Fire(),"Bounded rocket slot "+n+" can launch");Cool();}Check(ship.ActiveRockets==PlanetSpacecraft.RocketCapacity&&!Fire(),"Full projectile pool rejects overflow without recycling live shots");for(int i=0;i<2300;i++)ship.IntegrateRockets(.02f);Check(ship.ActiveRockets==0,"All capped-pool shots eventually explode and release their slots");Cool();
            Vector3 impact=world.Base.Offset(new Vector2(0,6500));for(int i=0;surface.SampleHeight(impact)<world.definition.oceanHeight+30&&i<64;i++){float a=i*2.39996323f;impact=world.Base.Offset(new Vector2(Mathf.Cos(a)*6500,Mathf.Sin(a)*6500));}Check(surface.SampleHeight(impact)>world.definition.oceanHeight,"Impact fixture finds dry land outside starting refuges");up=impact;east=Vector3.Cross(Vector3.up,up).normalized;SetShip(surface.GetSurfacePositionPrecise(impact,240),-up,east,new Double3());Cool();int hits=encounter.RocketImpacts;Check(Fire(),"Rocket launches toward the planet under the cockpit sight");world.Paused=false;var clock=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<180&&ship.ActiveRockets>0;i++)ship.IntegrateRockets(.02f);clock.Stop();report.impactSubmissionMs=clock.Elapsed.TotalMilliseconds;Check(encounter.RocketImpacts==hits+1&&ship.ActiveRockets==0,"Swept terrain impact detonates the rocket before its fuse");Check(encounter.NukesDetonated==0&&world.definition.Edits.Count==0,"Conventional rocket neither triggers a nuclear cloud nor consumes a persistent nuke crater");Check(PlanetEncounter.RocketBlastRadius<120,"Rocket blast radius is smaller than a nuclear blast");
            world.SetShipControl(false);world.Rig.SetFocusDirection(impact);world.Rig.Distance=1000;world.Rig.RefreshPose();double burstUntil=Time.realtimeSinceStartupAsDouble+.3;while(Time.realtimeSinceStartupAsDouble<burstUntil){RenderPipeline.SubmitRenderRequest(world.View,new RenderPipeline.StandardRequest{destination=target});yield return null;}var withBurst=Capture("rocket-impact");foreach(var fx in FindObjectsByType<VisualEffect>(FindObjectsSortMode.None))if(fx.name=="Pooled ship rocket burst"){report.burstParticles+=fx.aliveParticleCount;fx.gameObject.SetActive(false);}var withoutBurst=Capture("without-burst");for(int i=0;i<withBurst.Length;i++)if(Mathf.Abs(withBurst[i].r-withoutBurst[i].r)+Mathf.Abs(withBurst[i].g-withoutBurst[i].g)+Mathf.Abs(withBurst[i].b-withoutBurst[i].b)>15)report.burstPixels++;Check(report.burstParticles>0&&report.burstPixels>10,"Conventional impact explosion spawns particles and visibly renders above the terrain");world.Paused=true;
            // Actual N binding: the enlarged crater is separate from its damage radius.
            var screen=new Vector2(world.View.pixelWidth*.5f,world.View.pixelHeight*.5f);Check(world.Rig.GroundPoint(screen,out var nukePoint),"N-key fixture resolves the terrain under the sight");float original=surface.SampleHeight(nukePoint);Check(world.TryTestNukeAtCursor(screen),"Original N-key nuke handler still accepts terrain targets");report.nukeDepth=original-surface.SampleHeight(nukePoint);Check(report.nukeDepth>57&&report.nukeDepth<58,"N-key crater radius is 360 metres with about 57.6 metres of centre deformation");var rim=(nukePoint+Vector3.Cross(Vector3.up,nukePoint).normalized*(250/world.definition.radius)).normalized;Check(surface.SampleHeight(rim)<PlanetTerrainEdits.BaseHeight(world.definition,rim)-10,"Enlarged crater deforms ground beyond the previous 120 metre radius");
            // A live GPU blast writes exact destinations, preserves far zombies, and respects refuges.
            int index=world.unitCount;Check(encounter.Spawn(3,2,31,17)==3,"Attraction fixture creates GPU zombie records");var tangent=Vector3.Cross(Vector3.up,impact).normalized;var positions=new[]{(impact+tangent*(400/world.definition.radius)).normalized,(impact+tangent*(3000/world.definition.radius)).normalized,(world.Base.Homes[0]+tangent*(1700/world.definition.radius)).normalized};var units=new UnitState[3];for(int i=0;i<3;i++)units[i]=new UnitState{position=CubeSphere.Encode(positions[i]),previous=CubeSphere.Encode(positions[i]),destination=CubeSphere.Encode(positions[i]),flags=1|262144|524288|64,health=1000,packed=2u|(31u<<8),target=uint.MaxValue,group=17};world.UnitsForValidation.SetData(units,0,index,3);encounter.EmitExplosionNoiseForValidation(impact,600);var heard=ReadUnit(index);Check(CubeSphere.ArcDistance(CubeSphere.Decode(heard.destination),impact,world.definition.radius)<.2f&&(heard.flags&64)==0,"Nearby zombie receives the exact epicentre and resumes movement");Check(ReadUnit(index+1).destination==units[1].destination,"Distant zombie keeps its existing destination");encounter.EmitExplosionNoiseForValidation(world.Base.Homes[0],2000);Check(ReadUnit(index+2).destination==units[2].destination,"An explosion inside the protected starting base cannot lure zombies into it");
            world.Paused=false;double until=Time.realtimeSinceStartupAsDouble+3;while(Time.realtimeSinceStartupAsDouble<until)yield return null;world.Paused=true;var moved=ReadUnit(index);report.zombieTravel=CubeSphere.ArcDistance(positions[0],impact,world.definition.radius)-CubeSphere.ArcDistance(CubeSphere.Decode(moved.position),impact,world.definition.radius);Check(report.zombieTravel>1,"Zombie actually converges toward the explosion over subsequent GPU simulation ticks");
            report.fired=ship.RocketsFired;report.exploded=ship.RocketsExploded;report.timedOut=ship.RocketsTimedOut;Check(report.fired==report.exploded&&ship.ActiveRockets==0,"No rocket remains unexploded after impact and timeout tests");world.AutomaticPlayerStep=true;
        }
        void OnDestroy(){if(world!=null)world.AutomaticPlayerStep=true;if(target!=null){target.Release();Destroy(target);}}
    }
}
